 28	// PrePromptState stores the state captured before a user prompt
 29	type PrePromptState struct {
 30		SessionID      string   `json:"session_id"`
 31		Timestamp      string   `json:"timestamp"`
 32		UntrackedFiles []string `json:"untracked_files"`
 33	
 34		// UntrackedScanSkipped records that the pre-prompt untracked scan failed
 35		// (e.g. the status walk breached its wall-clock budget). Turn-end must
 36		// then skip new-file detection entirely: with no baseline, every
 37		// untracked file in the worktree would be misreported as created by this
 38		// turn.
 39		UntrackedScanSkipped bool `json:"untracked_scan_skipped,omitempty"`
 40	
 41		// TranscriptOffset is the unified transcript position when this state was captured.
 42		// For Claude Code (JSONL), this is the line count.
 43		// For Gemini CLI (JSON), this is the message count.
 44		// Zero means not set or session just started.
 45		TranscriptOffset int `json:"transcript_offset,omitempty"`
 46	
 47		// LastTranscriptIdentifier is the agent-specific identifier at the transcript position.
 48		// UUID for Claude Code, message ID for Gemini CLI. Optional metadata.
 49		LastTranscriptIdentifier string `json:"last_transcript_identifier,omitempty"`
 50	
 51		// Deprecated: StartMessageIndex is the old Gemini-specific field.
 52		// Migrated to TranscriptOffset on load.
 53		StartMessageIndex int `json:"start_message_index,omitempty"`
 54	
 55		// Deprecated: StepTranscriptStart is the old Claude-specific field.
 56		// Migrated to TranscriptOffset on load.
 57		StepTranscriptStart int `json:"step_transcript_start,omitempty"`
 58	
 59		// Deprecated: LastTranscriptLineCount is the oldest name for transcript position.
 60		// Migrated to TranscriptOffset on load.
 61		LastTranscriptLineCount int `json:"last_transcript_line_count,omitempty"`
 62	}
