 64	// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
 65	// This nil-vs-empty distinction lets DetectFileChanges know whether to skip new-file detection.
 66	// When the receiver is non-nil but UntrackedFiles is nil (e.g., old state files deserialized with
 67	// "untracked_files": null), returns an empty non-nil slice so that all current untracked files
 68	// are correctly treated as new.
 69	func (s *PrePromptState) PreUntrackedFiles() []string {
 70		if s == nil {
 71			return nil
 72		}
 73		if s.UntrackedFiles == nil {
 74			return []string{}
 75		}
 76		return s.UntrackedFiles
 77	}
 78	
 79	// normalizePrePromptState migrates deprecated fields after loading from JSON.
 80	func (s *PrePromptState) normalizePrePromptState() {
 81		// Migrate the oldest field to the intermediate field first
 82		if s.StepTranscriptStart == 0 && s.LastTranscriptLineCount > 0 {
 83			s.StepTranscriptStart = s.LastTranscriptLineCount
 84		}
 85		s.LastTranscriptLineCount = 0
 86	
 87		// Migrate all deprecated fields to the unified TranscriptOffset
 88		if s.TranscriptOffset == 0 {
 89			if s.StepTranscriptStart > 0 {
 90				s.TranscriptOffset = s.StepTranscriptStart
 91			} else if s.StartMessageIndex > 0 {
 92				s.TranscriptOffset = s.StartMessageIndex
 93			}
 94		}
 95		s.StepTranscriptStart = 0
 96		s.StartMessageIndex = 0
 97	}
