 99	// unknownSessionID is the fallback session ID used when no session ID is provided.
100	const unknownSessionID = "unknown"
101	
102	// CapturePrePromptState captures current untracked files and transcript position before a prompt
103	// and saves them to a state file.
104	//
105	// The agent parameter is used to determine the transcript position via TranscriptAnalyzer.
106	// If the agent does not implement TranscriptAnalyzer, the transcript offset will be 0.
107	// The sessionRef parameter is optional — if empty, transcript position won't be captured.
108	//
109	// Works correctly from any subdirectory within the repository.
110	func CapturePrePromptState(ctx context.Context, ag agent.Agent, sessionID, sessionRef string) error {
111		if sessionID == "" {
112			sessionID = unknownSessionID
113		}
114	
115		if err := validation.ValidateSessionID(sessionID); err != nil {
116			return fmt.Errorf("invalid session ID for pre-prompt state: %w", err)
117		}
118	
119		// Open the shared .entire root and ensure tmp/ exists under it.
120		root, err := openTmpDir(ctx)
121		if err != nil {
122			return err
123		}
124	
125		// Get list of untracked files (excluding .entire directory itself).
126		// Fail open on error: hooks must never break the agent, and the rest of
127		// the snapshot (transcript position) is still worth capturing. The
128		// skipped-scan marker tells turn-end to disable new-file detection.
129		untrackedFiles, scanSkipped := untrackedFilesOrSkip(ctx)
130	
131		// Get transcript position using TranscriptAnalyzer if available
132		var transcriptOffset int
133		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok && sessionRef != "" {
134			pos, posErr := analyzer.GetTranscriptPosition(sessionRef)
135			if posErr != nil {
136				logging.Warn(logging.WithComponent(ctx, "state"), "failed to get transcript position",
137					slog.String("error", posErr.Error()))
138			} else {
139				transcriptOffset = pos
140			}
141		}
142	
143		// Create state file using os.Root for traversal-resistant write
144		state := PrePromptState{
145			SessionID:            sessionID,
146			Timestamp:            time.Now().UTC().Format(time.RFC3339),
147			UntrackedFiles:       untrackedFiles,
148			UntrackedScanSkipped: scanSkipped,
149			TranscriptOffset:     transcriptOffset,
150		}
151	
152		data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
153		if err != nil {
154			return fmt.Errorf("failed to marshal state: %w", err)
155		}
156	
157		if err := entiredir.WriteFile(root, tmpFile("pre-prompt-%s.json", sessionID), data, 0o600); err != nil {
158			return fmt.Errorf("failed to write state file: %w", err)
159		}
160	
161		logging.Debug(logging.WithComponent(ctx, "state"), "captured state before prompt",
162			slog.Int("untracked_files", len(untrackedFiles)),
163			slog.Int("transcript_offset", transcriptOffset))
164		return nil
165	}
