167	// LoadPrePromptState loads previously captured state.
168	// Returns nil if no state file exists.
169	func LoadPrePromptState(ctx context.Context, sessionID string) (*PrePromptState, error) {
170		if err := validation.ValidateSessionID(sessionID); err != nil {
171			return nil, fmt.Errorf("invalid session ID for pre-prompt state: %w", err)
172		}
173	
174		root, err := entiredir.OpenForRead(ctx)
175		if err != nil {
176			// .entire doesn't exist yet — no state file
177			if errors.Is(err, fs.ErrNotExist) {
