209	// cleanupTmpStateFile removes one state file from .entire/tmp, treating a
210	// missing directory as already clean.
211	func cleanupTmpStateFile(ctx context.Context, fileName string) error {
212		root, err := entiredir.OpenForRead(ctx)
213		if err != nil {
214			if errors.Is(err, fs.ErrNotExist) {
215				return nil // .entire doesn't exist, nothing to clean up
216			}
217			return fmt.Errorf("failed to open %s: %w", paths.EntireDir, err)
218		}
