223	// FileChanges holds categorized file changes from git status.
224	type FileChanges struct {
225		Modified []string // Modified or staged files
226		New      []string // Untracked files (filtered if previouslyUntracked provided)
227		Deleted  []string // Deleted files (staged or unstaged)
228	}
