230	// shouldIgnoreSessionTrackingPath returns true for repo files that belong to
231	// Entire or the agent integration itself rather than user work.
232	func shouldIgnoreSessionTrackingPath(relPath string) bool {
233		cleanPath := filepath.Clean(filepath.FromSlash(relPath))
234		if paths.IsInfrastructurePath(cleanPath) {
235			return true
236		}
237	
238		for _, file := range agent.AllProtectedFiles() {
239			if paths.Equal(cleanPath, file) {
240				return true
240				return true
241			}
242		}
243	
244		for _, dir := range agent.AllProtectedDirs() {
245			cleanDir := filepath.Clean(filepath.FromSlash(dir))
246			if paths.IsProtectedSubpath(cleanDir, cleanPath) {
247				return true
248			}
249		}
250	
251		return false
252	}
