398	// FilterAndNormalizePaths converts absolute paths to relative and filters out
399	// infrastructure paths and paths outside the repo.
400	func FilterAndNormalizePaths(files []string, cwd string) []string {
401		var result []string
402		for _, file := range files {
403			relPath := paths.ToRelativePath(file, cwd)
404			if relPath == "" {
405				continue // outside repo
406			}
407			if shouldIgnoreSessionTrackingPath(relPath) {
408				continue
409			}
410			result = append(result, filepath.ToSlash(relPath))
411		}
412		return result
413	}
414	
415	// mergeUnique appends elements from extra into base, skipping duplicates already in base.
416	func mergeUnique(base, extra []string) []string {
417		if len(extra) == 0 {
418			return base
419		}
420		seen := make(map[string]bool, len(base))
421		for _, s := range base {
422			seen[s] = true
423		}
424		for _, s := range extra {
425			if !seen[s] {
426				seen[s] = true
427				base = append(base, s)
428			}
429		}
430		return base
431	}
432	
433	// entireTmpName is .entire/tmp expressed relative to the .entire root, which is
434	// the coordinate every read and write below uses.
435	var entireTmpName = entiredir.MustName(paths.EntireTmpDir)
436	
437	// tmpFile formats a state file name relative to the .entire root. The format
438	// arguments are already-validated session and tool-use IDs; the root confines
439	// the resulting open regardless.
440	func tmpFile(format string, args ...any) string {
441		return entireTmpName + "/" + fmt.Sprintf(format, args...)
442	}
443	
