415	// mergeUnique appends elements from extra into base, skipping duplicates already in base.
416	func mergeUnique(base, extra []string) []string {
417		if len(extra) == 0 {
418			return base
419		}
420		seen := make(map[string]bool, len(base))
421		for _, s := range base {
422			seen[s] = true
423		}
424		for _, s := range extra {
425			if !seen[s] {
426				seen[s] = true
427				base = append(base, s)
428			}
429		}
430		return base
431	}
