464	// untrackedFilesOrSkip runs the pre-prompt/pre-task untracked scan, degrading
465	// instead of failing. Deliberately wider than the status-budget feature that
466	// introduced it: EVERY scan error fails open — budget breach, repo-open
467	// failure, corrupted .git, anything — because these captures run inside
468	// TurnStart/SubagentStart hooks, and any error propagated from here used to
469	// fail the hook and break the agent's turn. That fail-hook behavior was the
470	// bug, not a safety property: the scan only feeds new-file detection, so the
471	// correct degrade is to warn, mark the scan skipped (the paired end-hook then
472	// disables new-file detection for the turn), and let capture proceed with
473	// transcript-derived data.
474	func untrackedFilesOrSkip(ctx context.Context) (untrackedFiles []string, scanSkipped bool) {
475		untrackedFiles, err := getUntrackedFilesForState(ctx)
476		if err != nil {
477			logStatusDegrade(logging.WithComponent(ctx, "state"),
478				"untracked-file scan failed; capture degraded: new-file detection disabled for this turn", err)
479			return nil, true
480		}
481		return untrackedFiles, false
482	}
