484	// logStatusDegrade logs a status-derived degrade at the appropriate level:
485	// budget breaches were already warned about — with repo root, elapsed, and
486	// budget — by the gitrepo layer at the moment of the breach, so re-warning
487	// here would double-log the same event; they get Debug. Any other status
488	// error (repo-open failure, corrupted .git, …) has no other warning source
489	// and keeps Warn.
490	func logStatusDegrade(ctx context.Context, msg string, err error) {
491		if errors.Is(err, gitrepo.ErrStatusBudgetExceeded) {
492			logging.Debug(ctx, msg, slog.String("error", err.Error()))
493			return
494		}
495		logging.Warn(ctx, msg, slog.String("error", err.Error()))
496	}
