498	// getUntrackedFilesForState returns a list of untracked files using go-git
499	// Excludes .entire directory
500	func getUntrackedFilesForState(ctx context.Context) ([]string, error) {
501		repo, err := openRepository(ctx)
502		if err != nil {
503			return nil, err
504		}
505		defer repo.Close()
506	
507		status, err := gitrepo.StatusWithBudget(ctx, repo)
508		if err != nil {
509			return nil, err //nolint:wrapcheck // already present in codebase
510		}
511	
512		untrackedFiles := []string{}
513		for file, st := range status {
514			if st.Worktree == git.Untracked {
515				if !shouldIgnoreSessionTrackingPath(file) {
516					untrackedFiles = append(untrackedFiles, file)
517				}
518			}
519		}
520	
521		return untrackedFiles, nil
522	}
