 79	// search performs a v4 query-serve search across every cell that hosts the
 80	// caller's in-scope repos, then merges the per-cell responses into one
 81	// response. It is the semantic sibling of searchAllCells (code): resolve
 82	// scope → group by hosting cell → one query-serve call per cell → tiered
 83	// merge.
 84	//
 85	// Scope follows Config.ScopeSlugs — an explicit repo filter wins over
 86	// --all-repos (the more specific filter scopes the search):
 87	//   - unfiltered (repo:* / --all-repos with no explicit filter) → every cell
 88	//     is queried with NO repo param, so query-serve returns everything the
 89	//     caller's token authorizes there (matching the BFF and keeping the query
 90	//     small for users with many repos).
 91	//   - explicit repo filter(s) or the current-repo default → the slugs are
 92	//     resolved via truncation-proof exact-match lookups and each cell is
 93	//     scoped to the ULIDs it hosts.
 94	//
 95	// Completeness caveats (truncated index, failed regions) are returned as
 96	// Response.Warnings for the caller to surface.
 97	func (s *semanticSearchV4Session) search(ctx context.Context, cfg search.Config) (*search.Response, error) {
 98		if err := search.ValidateRepoFilters(cfg.Repos); err != nil {
 99			return nil, err //nolint:wrapcheck // user-facing validation message
100		}
101	
102		coreClient, err := s.client()
103		if err != nil {
104			if errors.Is(err, auth.ErrNotLoggedIn) {
105				return nil, loginHintErr(err)
106			}
107			return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
108		}
109	
110		slugs, allRepos := cfg.ScopeSlugs()
111		var cells []cellGroup
112		var skipped []string
113		var warnings []string
114		indexTruncated := false
115		scoped := !allRepos
116		if scoped {
117			if len(slugs) == 0 {
118				return nil, errors.New("semantic search: could not determine the repository to search")
119			}
120			entries, err := s.resolveScope(ctx, slugs)
121			if err != nil {
122				return nil, err
123			}
124			// Scoped requests pin the picked placement's ULID (repoIDs below),
125			// which query-serve resolves from its all-accessible byID set.
126			cells, skipped = groupReposByCell(entries)
127		} else {
128			index, err := s.listFullIndex(ctx)
129			if err != nil {
130				return nil, fmt.Errorf("semantic search: listing repos for cell discovery: %w", err)
131			}
132			if index.Truncated {
133				// Debug, not Warn: the user-facing channel is the Warnings entry;
134				// slog's default handler would print a Warn straight to stderr on
135				// commands whose context carries no logger.
136				logging.Debug(ctx, "semantic search: repo index truncated; cross-repo results may be incomplete")
137				warnings = append(warnings, "repo index truncated; cross-repo results may be incomplete")
138				indexTruncated = true
139			}
140			// Broad requests send no repo pins; query-serve narrows pin-less
141			// scope by the same election routedRepoPlacement picks by (ENT-1776),
142			// so one grouping serves both request shapes.
143			cells, skipped = groupReposByCell(index.Repos)
144		}
145		skipped = reportableSkippedRepos(ctx, scoped, len(cells), skipped)
146		if len(skipped) > 0 {
147			warnings = append(warnings, fmt.Sprintf("skipped %d repo(s) with no searchable placement (missing or not ready): %s", len(skipped), strings.Join(skipped, ", ")))
148		}
149		// The BFF's scope-loss channels (search.ts): a truncated repo index means
150		// broad coverage silently misses repos; an explicitly-filtered repo
151		// skipped as not-ready narrows the promised scope. Unfiltered skips stay
152		// silent — nothing advertised was narrowed.
153		scopeNarrowed := scoped && len(skipped) > 0
154	
155		if len(cells) == 0 {
156			resp := &search.Response{Results: []search.Result{}, Page: 1, Warnings: warnings, Counts: &search.TypeCounts{}}
157			if indexTruncated {
158				// Every facet count is a lower bound, not an exact zero — same
159				// contract as the BFF's zero-routable-cells answer.
160				resp.Truncated = true
161				resp.CountsLowerBound = map[string]bool{
162					facetRepos: true, facetCheckpoints: true, facetCommits: true, facetPRs: true, facetSessions: true,
163				}
164			}
165			if indexTruncated || scopeNarrowed {
166				resp.Partial = true
167				resp.CoverageIncomplete = true
168			}
169			return resp, nil
170		}
171		resolveCellBaseURLs(ctx, s.clusterClient(coreClient), cells)
172	
173		results, err := fanOutCells(ctx, s.insecureHTTP, semanticSearchV4CellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*search.Response, error) {
174			// Scoped: restrict the cell to the ULIDs it hosts. Unfiltered: send no
175			// repo param and let query-serve search everything the token
176			// authorizes in that cell (avoids per-request repo-filter caps for
177			// large accounts).
178			var repoIDs []string
179			if scoped {
180				repoIDs = group.repoIDs
181			}
182			return search.CellV4(ctx, client, cfg, repoIDs)
183		})
184		if err != nil {
185			if errors.Is(err, auth.ErrNotLoggedIn) {
186				return nil, loginHintErr(err)
187			}
188			return nil, fmt.Errorf("semantic search: %w", err)
189		}
190	
191		resp, err := mergeSemanticV4Responses(ctx, cfg.Limit, cfg.Page, results)
192		if err != nil {
193			return nil, err
194		}
195		resp.Warnings = append(warnings, resp.Warnings...)
196		if indexTruncated {
197			resp.Truncated = true
198		}
199		if indexTruncated || scopeNarrowed {
200			resp.Partial = true
201			resp.CoverageIncomplete = true
202		}
203		return resp, nil
204	}
