350	// tierOf returns a result's tier, or -1 when unset (dropped by the merge,
351	// like every tier outside 0/1 — see rankSemanticResults).
352	func tierOf(r search.Result) int {
353		if r.Meta.Tier == nil {
354			return -1
355		}
356		return *r.Meta.Tier
357	}
