366	// rerankOf returns query-serve's cross-encoder relevance score, or 0 when the
367	// row was not reranked (its cell fell back). Rows without a score sort after
368	// reranked ones, matching the BFF's rerankOf.
369	func rerankOf(r search.Result) float64 {
370		if r.Meta.RerankScore != nil {
371			return *r.Meta.RerankScore
372		}
373		return 0
374	}
375	
376	// semanticCellPage is one cell's successful response.
377	type semanticCellPage struct {
378		body *search.Response
379	}
380	
381	// classifySemanticCells splits per-cell outcomes into successful pages, hard
382	// failures, and quietly-skipped cells. A cell is skipped — not failed — when
383	// it can't serve the search yet: its gateway has no query-serve route, or the
384	// cluster catalog doesn't expose the placement's jurisdiction at all (a cell
385	// mid-onboarding). Neither is worth warning the user about on every search.
386	func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []string, lastErr error) {
387		var skipped, unmatched []string
388		var skipErrs []error
389		var unmatchedErr error
390		for _, r := range results {
391			switch {
392			case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
393				skipped = append(skipped, r.group.label())
394				skipErrs = append(skipErrs, r.err)
395			case errors.Is(r.err, search.ErrRepoFilterUnmatched):
396				// The cell answered; the repo filter just matched nothing there.
397				// Quiet like a skip when another cell has results, but if NO cell
398				// matches it must surface as a repo problem, never a region one.
399				unmatched = append(unmatched, r.group.label())
400				unmatchedErr = r.err
401			case r.err != nil:
402				lastErr = r.err
403				failed = append(failed, r.group.label())
404			case r.value != nil:
405				pages = append(pages, semanticCellPage{body: r.value})
406			}
407		}
408		if len(skipped) > 0 {
409			logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
410		}
411		if len(unmatched) > 0 {
412			// unmatchedErr carries the server's own message (CellV4 wraps it into
413			// the sentinel) — keep it visible here for diagnosis.
414			logging.Debug(ctx, "semantic search: cells where the repo filter matched nothing", "unmatched_cells", unmatched, "error", unmatchedErr.Error())
415		}
416		if len(pages) == 0 && lastErr == nil {
417			switch {
418			case len(unmatched) > 0:
419				// Takes priority over the region message: a cell answering proves
420				// its region serves semantic search.
421				lastErr = errNoRepoAvailable
422			case len(skipped) > 0:
423				// Same message as the bare sentinel, but keep every per-cell skip
424				// cause in the chain: the two "region" variants (gateway without
425				// query-serve vs. client-side jurisdiction skip) are different
426				// failures and telemetry classifies them from the typed causes.
427				// All causes — not just the last — so a mixed-cause fan-out
428				// classifies by the classifier's precedence, not cell order.
429				lastErr = &hintError{msg: errNoRegionAvailable.Error(), errs: skipErrs}
430			}
431		}
432		return pages, failed, lastErr
433	}
434	
435	// errNoRepoAvailable is returned when at least one cell answered but none
436	// matched the repo filter. A typo'd name or missing access cannot reach this
437	// point — resolveScope already validated the slug against the control-plane
438	// repo index — so the message names only the causes that survive: query-serve
439	// hasn't indexed the repo, or its owner org isn't enabled for semantic search.
440	var errNoRepoAvailable = errors.New("semantic search cannot search this repo yet — it may not be indexed, or semantic search may not be enabled for its owner")
441	
442	// errNoRegionAvailable is returned when every queried cell lacks query-serve.
443	var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")
444	
445	// tier0Row pairs a tier-0 result with its rank within the cell that returned
446	// it — the selection order the mixed-capability fallback preserves (see
447	// sortTier0Rows).
448	type tier0Row struct {
449		r        search.Result
450		cellRank int
451	}
452	
453	// rankSemanticResults buckets every page's rows and applies the SAME ordering
454	// the BFF's cross-cell merge uses (see the ordering contract on
455	// mergeSemanticV4Responses): repos first by retrieval score desc, then tier 0
456	// (sortTier0Rows), then tier 1 by rerank desc with retrieval Score tiebreak.
457	// Every other non-repo row — tier 2 (the retired ANN-only fallback, still
458	// emitted by un-redeployed cells) and rows with no tier at all — is DROPPED,
459	// exactly as the BFF drops them. Ordering by rerank score — not BM25 or the
460	// per-namespace retrieval Score — is what keeps the CLI in parity with the
461	// web: query-serve documents that Score "is not the field results are ordered
462	// by … sorting by it undoes reranking."
463	func rankSemanticResults(pages []semanticCellPage) (merged []search.Result) {
464		var repos, tier1 []search.Result
465		var tier0 []tier0Row
466		for _, p := range pages {
467			cellRank := 0
468			for _, r := range p.body.Results {
469				switch {
470				case r.Type == search.TypeRepo:
471					repos = append(repos, r)
472				case tierOf(r) == 0:
473					tier0 = append(tier0, tier0Row{r: r, cellRank: cellRank})
474					cellRank++
475				case tierOf(r) == 1:
476					tier1 = append(tier1, r)
477				}
478			}
479		}
480		sort.SliceStable(repos, func(i, j int) bool { return repos[i].Meta.Score > repos[j].Meta.Score })
481		merged = append(merged, repos...)
482		sortTier0Rows(tier0)
483		// Tier 1: rerank score decides, retrieval Score breaks ties. Rows whose
484		// cell fell back (no rerank score) sort last, matching the BFF.
485		sort.SliceStable(tier1, func(i, j int) bool {
486			if ri, rj := rerankOf(tier1[i]), rerankOf(tier1[j]); ri != rj {
487				return ri > rj
488			}
489			return tier1[i].Meta.Score > tier1[j].Meta.Score
490		})
491		for _, t := range tier0 {
492			merged = append(merged, t.r)
493		}
494		merged = append(merged, tier1...)
495		return merged
496	}
497	
498	// sortTier0Rows orders the tier-0 band the way the BFF's sortTier0 does
499	// (ENT-1431). When EVERY row was judged by the cross-encoder, rerank score
500	// decides and BM25 breaks ties. When any row is missing a rerank score — its
501	// cell predates tier-0 reranking — a global rerank sort would demote all of
502	// that cell's full-phrase hits regardless of relevance, so instead the rows are
503	// interleaved positionally (each cell's #1, then each cell's #2, …), preserving
504	// every cell's own selection order, with BM25 breaking ties between same-rank
505	// rows. Converges to rerank-first once every cell is current.
506	func sortTier0Rows(tier0 []tier0Row) {
507		allScored := true
508		for _, t := range tier0 {
509			if t.r.Meta.RerankScore == nil {
510				allScored = false
511				break
512			}
513		}
514		if allScored {
515			sort.SliceStable(tier0, func(i, j int) bool {
516				if ri, rj := rerankOf(tier0[i].r), rerankOf(tier0[j].r); ri != rj {
517					return ri > rj
518				}
519				return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
520			})
521			return
522		}
523		sort.SliceStable(tier0, func(i, j int) bool {
524			if tier0[i].cellRank != tier0[j].cellRank {
525				return tier0[i].cellRank < tier0[j].cellRank
526			}
527			return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
528		})
529	}
530	
531	// dedupSemanticResults removes cross-cell duplicate SESSION rows, keeping the
532	// first (higher-ranked) copy — the BFF's exact rule: sessions are the one type
533	// that legitimately repeats across cells (a crosslinked session attached to
534	// repos homed in different cells), while repo-bound types are canonical to one
535	// cell since the fan-out routes each repo to its single home placement
536	// (ENT-1672/ENT-1776). The key is the global session id when present, else the
537	// repo-qualified carrier checkpoint (server-folded legacy rows, ENT-1595);
538	// rows with neither are always kept.
539	func dedupSemanticResults(merged []search.Result) []search.Result {
540		seen := make(map[string]bool)
541		deduped := merged[:0]
542		for _, r := range merged {
543			if r.Type != search.TypeSession {
544				deduped = append(deduped, r)
545				continue
546			}
547			id := r.DedupID()
548			if id == "" {
549				deduped = append(deduped, r)
550				continue
551			}
552			key := r.Type + "\x00" + id
553			if seen[key] {
554				continue
555			}
556			seen[key] = true
557			deduped = append(deduped, r)
558		}
559		return deduped
560	}
561	
562	// Facet names for the wire maps (truncated_types / counts_lower_bound) — the
563	// BFF's RESULT_TYPE_TO_FACET values.
564	const (
565		facetRepos       = "repos"
566		facetCheckpoints = "checkpoints"
567		facetCommits     = "commits"
568		facetPRs         = "prs"
569		facetSessions    = "sessions"
570	)
571	
572	// semanticFacetOf maps a wire result type to its counts/truncation facet name
573	// (the BFF's RESULT_TYPE_TO_FACET). Unknown types have no facet: they are kept
574	// in results, exempt from the per-type cap, and counted only in the total.
575	func semanticFacetOf(typ string) (string, bool) {
576		switch typ {
577		case search.TypeRepo:
578			return facetRepos, true
579		case search.TypeCheckpoint:
580			return facetCheckpoints, true
581		case search.TypeCommit:
582			return facetCommits, true
583		case search.TypePR:
584			return facetPRs, true
585		case search.TypeSession:
586			return facetSessions, true
587		}
588		return "", false
589	}
590	
591	// capSemanticPerType applies the BFF's per-type window: walk the merged list
592	// in order and keep at most `limit` rows of each facet, recording which facets
593	// overflowed. Rows without a facet mapping are kept uncounted.
594	func capSemanticPerType(merged []search.Result, limit int) ([]search.Result, map[string]bool) {
595		truncated := make(map[string]bool)
596		if limit <= 0 {
597			return merged, truncated
598		}
599		perFacet := make(map[string]int, 5)
600		out := merged[:0]
601		for _, r := range merged {
602			facet, ok := semanticFacetOf(r.Type)
603			if !ok {
604				out = append(out, r)
605				continue
606			}
607			perFacet[facet]++
608			if perFacet[facet] > limit {
609				truncated[facet] = true
610				continue
611			}
612			out = append(out, r)
613		}
614		return out, truncated
615	}
616	
617	// deriveSemanticCounts computes total and per-type counts from the FINAL
618	// merged list — the BFF's per-type contract (ENT-1363): counts describe
619	// exactly what the caller can see, never the cells' corpus-count passes,
620	// with counts_lower_bound marking the facets whose lists were capped.
621	func deriveSemanticCounts(merged []search.Result) (int, *search.TypeCounts) {
622		counts := &search.TypeCounts{}
623		for _, r := range merged {
624			switch r.Type {
625			case search.TypeRepo:
626				counts.Repos++
627			case search.TypeCheckpoint:
628				counts.Checkpoints++
629			case search.TypeCommit:
630				counts.Commits++
631			case search.TypePR:
632				counts.PRs++
633			case search.TypeSession:
634				counts.Sessions++
635			}
636		}
637		return len(merged), counts
638	}
639	
640	// mergeSemanticV4Responses interleaves per-cell query-serve responses into
641	// one final page. THE CROSS-CELL MERGE ORDERING CONTRACT lives here and in
642	// the BFF's mergeCellResponses (entire.io api/src/routes/search.ts) — the two
643	// implementations must stay byte-identical (ENT-1777); change one, change
644	// both, and update this block:
645	//
646	//  1. Band order: repo rows first (retrieval score desc), then tier 0, then
647	//     tier 1. Tier 2 and tier-less non-repo rows are dropped — the ANN-only
648	//     fallback tier is retired and only un-redeployed cells still emit it.
649	//     Band order deliberately overrides each cell's own post-fold final
650	//     order (entire-search#181 folds after ranking): the clients match each
651	//     other, not the leaf.
652	//  2. Tier 0: when every row carries a rerank score, rerank desc with BM25
653	//     tiebreak; when any cell predates tier-0 reranking, positional
654	//     interleave by in-cell rank with BM25 tiebreak (sortTier0Rows). Tier 1:
655	//     rerank desc, retrieval Score tiebreak. All sorts are STABLE — equal
656	//     keys keep cell-response order.
657	//  3. Dedupe AFTER ordering, BEFORE the per-type cap, sessions only, first
658	//     (highest-ranked) copy wins (dedupSemanticResults).
659	//  4. Per-type window: at most `limit` rows of each facet, overflow recorded
660	//     in truncated_types, unioned with the cells' own truncated_types
661	//     (capSemanticPerType). No global cut.
662	//  5. Counts and total derive from the FINAL list (deriveSemanticCounts);
663	//     counts_lower_bound == the capped facets.
664	//  6. Flags: truncated = any cell truncated; partial = truncated ∨ any cell
665	//     failed ∨ any cell partial ∨ mixed rerank capability; coverage_incomplete
666	//     = the same minus rerank-mix; reranked = every cell reranked (emitted
667	//     when any cell reported the field).
668	//
669	// Rerank scores share a space across cells (same Cohere model), so
670	// interleaving is meaningful. All-cells-failed is an error; a partial failure
671	// is noted in Warnings (and the flags) and the surviving cells are merged.
672	func mergeSemanticV4Responses(ctx context.Context, limit, page int, results []cellCallResult[*search.Response]) (*search.Response, error) {
673		pages, failed, lastErr := classifySemanticCells(ctx, results)
674		if len(pages) == 0 {
675			if lastErr != nil {
676				return nil, fmt.Errorf("semantic search: %w", lastErr)
677			}
678			return &search.Response{Results: []search.Result{}, Page: 1}, nil
679		}
680		var warnings []string
681		if len(failed) > 0 {
682			// Debug, not Warn: the warning below already reaches the user via
683			// Response.Warnings, and slog's default handler would print a Warn
684			// straight to stderr on commands whose context carries no logger.
685			logging.Debug(ctx, "semantic search: partial failure; results may be incomplete",
686				"succeeded", len(pages), "total", len(results), "failed_cells", failed)
687			warnings = append(warnings, fmt.Sprintf("search failed in %d of %d regions; results may be incomplete", len(failed), len(pages)+len(failed)))
688		}
689	
690		merged := rankSemanticResults(pages)
691		merged = dedupSemanticResults(merged)
692		merged, truncatedTypes := capSemanticPerType(merged, limit)
693		for _, p := range pages {
694			for facet, v := range p.body.TruncatedTypes {
695				if v {
696					truncatedTypes[facet] = true
697				}
698			}
699		}
700		if merged == nil {
701			merged = []search.Result{}
702		}
703	
704		total, counts := deriveSemanticCounts(merged)
705		resp := &search.Response{
706			Results:  merged,
707			Total:    total,
708			Page:     max(page, 1),
709			Counts:   counts,
710			Warnings: warnings,
711		}
712		if len(truncatedTypes) > 0 {
713			resp.TruncatedTypes = truncatedTypes
714			resp.CountsLowerBound = make(map[string]bool, len(truncatedTypes))
715			for facet := range truncatedTypes {
716				resp.CountsLowerBound[facet] = true
717			}
718		}
719	
