  1	package cli
  2	
  3	import (
  4		"context"
  5		"errors"
  6		"fmt"
  7		"sort"
  8		"strings"
  9		"sync"
 10		"time"
 11	
 12		"github.com/entireio/cli/cmd/entire/cli/api"
 13		"github.com/entireio/cli/cmd/entire/cli/auth"
 14		"github.com/entireio/cli/cmd/entire/cli/logging"
 15		"github.com/entireio/cli/cmd/entire/cli/search"
 16		"github.com/entireio/cli/internal/coreapi"
 17	)
 18	
 19	// semanticSearchV4CellTimeout bounds each per-cell v4 query (token exchange +
 20	// the query-serve call), mirroring codeSearchCellTimeout.
 21	const semanticSearchV4CellTimeout = 30 * time.Second
 22	
 23	// semanticSearchControlPlaneTimeout bounds each control-plane discovery call
 24	// (repo index / repo lookup) on the v4 path.
 25	const semanticSearchControlPlaneTimeout = 10 * time.Second
 26	
 27	// semanticSearcher performs one semantic search. The command layer builds one
 28	// per invocation (newSemanticSearcher) and every entry point — the one-shot
 29	// command, the TUI's initial fetch, interactive re-searches, and pagination —
 30	// calls through it, so all of them share one discovery cache.
 31	type semanticSearcher func(ctx context.Context, cfg search.Config) (*search.Response, error)
 32	
 33	// newSemanticSearcher returns the semantic-search entry for this invocation: a
 34	// v4 query-serve session (ENT-1055) that fans out across entire-api cells and
 35	// caches control-plane discovery across calls.
 36	func newSemanticSearcher(insecureHTTP bool) semanticSearcher {
 37		s := &semanticSearchV4Session{insecureHTTP: insecureHTTP}
 38		return s.search
 39	}
 40	
 41	// hintError swaps in a friendlier user-facing message while keeping the
 42	// underlying typed errors matchable with errors.Is/As — search outcome
 43	// telemetry classifies failures from the error chain (ENT-1938), so a hint
 44	// must never truncate it.
 45	type hintError struct {
 46		msg  string
 47		errs []error
 48	}
 49	
 50	func (e *hintError) Error() string   { return e.msg }
 51	func (e *hintError) Unwrap() []error { return e.errs }
 52	
 53	// loginHintErr maps auth.ErrNotLoggedIn to the standard login hint; other
 54	// errors pass through unchanged.
 55	func loginHintErr(err error) error {
 56		if errors.Is(err, auth.ErrNotLoggedIn) {
 57			return &hintError{msg: "not authenticated. Run 'entire login' to authenticate", errs: []error{err}}
 58		}
 59		return err
 60	}
 61	
 62	// semanticSearchV4Session holds per-invocation state for the v4 query-serve
 63	// path. Control-plane discovery (the repo index, per-slug repo lookups, the
 64	// cluster catalog) is stable for the life of one command, so it is resolved
 65	// once and reused across TUI re-searches and pagination instead of paying
 66	// several network round trips per keystroke-search. Identity tokens are NOT
 67	// cached here — fanOutCells mints them per search (at most one per
 68	// jurisdiction), which keeps expiry handling in the auth layer.
 69	type semanticSearchV4Session struct {
 70		insecureHTTP bool
 71	
 72		mu         sync.Mutex
 73		coreClient *coreapi.Client
 74		clusters   *cachedClusterClient
 75		fullIndex  *coreapi.ListReposOutputBody        // unfiltered index, fetched at most once
 76		slugRepos  map[string][]coreapi.RepoIndexEntry // per-filter exact-match lookups
 77	}
 78	
 79	// search performs a v4 query-serve search across every cell that hosts the
 80	// caller's in-scope repos, then merges the per-cell responses into one
 81	// response. It is the semantic sibling of searchAllCells (code): resolve
 82	// scope → group by hosting cell → one query-serve call per cell → tiered
 83	// merge.
 84	//
 85	// Scope follows Config.ScopeSlugs — an explicit repo filter wins over
 86	// --all-repos (the more specific filter scopes the search):
 87	//   - unfiltered (repo:* / --all-repos with no explicit filter) → every cell
 88	//     is queried with NO repo param, so query-serve returns everything the
 89	//     caller's token authorizes there (matching the BFF and keeping the query
 90	//     small for users with many repos).
 91	//   - explicit repo filter(s) or the current-repo default → the slugs are
 92	//     resolved via truncation-proof exact-match lookups and each cell is
 93	//     scoped to the ULIDs it hosts.
 94	//
 95	// Completeness caveats (truncated index, failed regions) are returned as
 96	// Response.Warnings for the caller to surface.
 97	func (s *semanticSearchV4Session) search(ctx context.Context, cfg search.Config) (*search.Response, error) {
 98		if err := search.ValidateRepoFilters(cfg.Repos); err != nil {
 99			return nil, err //nolint:wrapcheck // user-facing validation message
100		}
101	
102		coreClient, err := s.client()
103		if err != nil {
104			if errors.Is(err, auth.ErrNotLoggedIn) {
105				return nil, loginHintErr(err)
106			}
107			return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
108		}
109	
110		slugs, allRepos := cfg.ScopeSlugs()
111		var cells []cellGroup
112		var skipped []string
113		var warnings []string
114		indexTruncated := false
115		scoped := !allRepos
116		if scoped {
117			if len(slugs) == 0 {
118				return nil, errors.New("semantic search: could not determine the repository to search")
119			}
120			entries, err := s.resolveScope(ctx, slugs)
121			if err != nil {
122				return nil, err
123			}
124			// Scoped requests pin the picked placement's ULID (repoIDs below),
125			// which query-serve resolves from its all-accessible byID set.
126			cells, skipped = groupReposByCell(entries)
127		} else {
128			index, err := s.listFullIndex(ctx)
129			if err != nil {
130				return nil, fmt.Errorf("semantic search: listing repos for cell discovery: %w", err)
131			}
132			if index.Truncated {
133				// Debug, not Warn: the user-facing channel is the Warnings entry;
134				// slog's default handler would print a Warn straight to stderr on
135				// commands whose context carries no logger.
136				logging.Debug(ctx, "semantic search: repo index truncated; cross-repo results may be incomplete")
137				warnings = append(warnings, "repo index truncated; cross-repo results may be incomplete")
138				indexTruncated = true
139			}
140			// Broad requests send no repo pins; query-serve narrows pin-less
141			// scope by the same election routedRepoPlacement picks by (ENT-1776),
142			// so one grouping serves both request shapes.
143			cells, skipped = groupReposByCell(index.Repos)
144		}
145		skipped = reportableSkippedRepos(ctx, scoped, len(cells), skipped)
146		if len(skipped) > 0 {
147			warnings = append(warnings, fmt.Sprintf("skipped %d repo(s) with no searchable placement (missing or not ready): %s", len(skipped), strings.Join(skipped, ", ")))
148		}
149		// The BFF's scope-loss channels (search.ts): a truncated repo index means
150		// broad coverage silently misses repos; an explicitly-filtered repo
151		// skipped as not-ready narrows the promised scope. Unfiltered skips stay
152		// silent — nothing advertised was narrowed.
153		scopeNarrowed := scoped && len(skipped) > 0
154	
155		if len(cells) == 0 {
156			resp := &search.Response{Results: []search.Result{}, Page: 1, Warnings: warnings, Counts: &search.TypeCounts{}}
157			if indexTruncated {
158				// Every facet count is a lower bound, not an exact zero — same
159				// contract as the BFF's zero-routable-cells answer.
160				resp.Truncated = true
161				resp.CountsLowerBound = map[string]bool{
162					facetRepos: true, facetCheckpoints: true, facetCommits: true, facetPRs: true, facetSessions: true,
163				}
164			}
165			if indexTruncated || scopeNarrowed {
166				resp.Partial = true
167				resp.CoverageIncomplete = true
168			}
169			return resp, nil
170		}
171		resolveCellBaseURLs(ctx, s.clusterClient(coreClient), cells)
172	
173		results, err := fanOutCells(ctx, s.insecureHTTP, semanticSearchV4CellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*search.Response, error) {
174			// Scoped: restrict the cell to the ULIDs it hosts. Unfiltered: send no
175			// repo param and let query-serve search everything the token
176			// authorizes in that cell (avoids per-request repo-filter caps for
177			// large accounts).
178			var repoIDs []string
179			if scoped {
180				repoIDs = group.repoIDs
181			}
182			return search.CellV4(ctx, client, cfg, repoIDs)
183		})
184		if err != nil {
185			if errors.Is(err, auth.ErrNotLoggedIn) {
186				return nil, loginHintErr(err)
187			}
188			return nil, fmt.Errorf("semantic search: %w", err)
189		}
190	
191		resp, err := mergeSemanticV4Responses(ctx, cfg.Limit, cfg.Page, results)
192		if err != nil {
193			return nil, err
194		}
195		resp.Warnings = append(warnings, resp.Warnings...)
196		if indexTruncated {
197			resp.Truncated = true
198		}
199		if indexTruncated || scopeNarrowed {
200			resp.Partial = true
201			resp.CoverageIncomplete = true
202		}
203		return resp, nil
204	}
205	
206	// client returns the cached control-plane client, creating it on first use.
207	func (s *semanticSearchV4Session) client() (*coreapi.Client, error) {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		if s.coreClient != nil {
211			return s.coreClient, nil
212		}
213		c, err := coreapi.New()
214		if err != nil {
215			return nil, err
216		}
217		s.coreClient = c
218		return c, nil
219	}
220	
221	// listFullIndex fetches (once) and caches the caller's full repo index, used
222	// for unfiltered searches and raw-ID filter matching.
223	func (s *semanticSearchV4Session) listFullIndex(ctx context.Context) (*coreapi.ListReposOutputBody, error) {
224		s.mu.Lock()
225		defer s.mu.Unlock()
226		if s.fullIndex != nil {
227			return s.fullIndex, nil
228		}
229		reposCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
230		defer cancel()
231		index, err := s.coreClient.ListRepos(reposCtx, coreapi.ListReposParams{})
232		if err != nil {
233			return nil, err
234		}
235		s.fullIndex = index
236		return index, nil
237	}
238	
239	// resolveScope resolves explicit repo filters (or the current-repo default)
240	// to index entries, deduped by repo ID. owner/name slugs use the exact-match
241	// ListRepos filter — immune to index truncation on large accounts — while raw
242	// IDs (no slash) fall back to matching against the full index. Zero matches
243	// is a clear error; a partially matched multi-repo filter proceeds with the
244	// matches, like resolveRepoFilters does for code search.
245	func (s *semanticSearchV4Session) resolveScope(ctx context.Context, slugs []string) ([]coreapi.RepoIndexEntry, error) {
246		var entries []coreapi.RepoIndexEntry
247		seen := make(map[string]bool, len(slugs))
248		for _, f := range slugs {
249			matched, err := s.lookupFilter(ctx, f)
250			if err != nil {
251				return nil, err
252			}
253			for _, e := range matched {
254				if !seen[e.ID] {
255					seen[e.ID] = true
256					entries = append(entries, e)
257				}
258			}
259		}
260		if len(entries) == 0 {
261			return nil, fmt.Errorf("no matching repositories found for %v (is the repo mirrored to Entire?)", slugs)
262		}
263		return entries, nil
264	}
265	
266	// lookupFilter resolves one repo filter to index entries, cached per session.
267	// Matching mirrors resolveRepoFilters: a gh/ prefix is stripped, owner/name
268	// matches full_name (case-insensitive, server-side exact match), and a raw
269	// ULID matches the index entry's ID.
270	func (s *semanticSearchV4Session) lookupFilter(ctx context.Context, filter string) ([]coreapi.RepoIndexEntry, error) {
271		s.mu.Lock()
