307	// clusterClient returns a cellCoreClient whose ListClusters is memoized for
308	// the session, so re-searches don't refetch the (stable) cluster catalog.
309	func (s *semanticSearchV4Session) clusterClient(inner *coreapi.Client) cellCoreClient {
310		s.mu.Lock()
311		defer s.mu.Unlock()
312		if s.clusters == nil {
313			s.clusters = &cachedClusterClient{inner: inner}
314		}
315		return s.clusters
316	}
