209		defer s.mu.Unlock()
210		if s.coreClient != nil {
211			return s.coreClient, nil
212		}
213		c, err := coreapi.New()
214		if err != nil {
215			return nil, err
216		}
217		s.coreClient = c
218		return c, nil
219	}
