221	// listFullIndex fetches (once) and caches the caller's full repo index, used
222	// for unfiltered searches and raw-ID filter matching.
223	func (s *semanticSearchV4Session) listFullIndex(ctx context.Context) (*coreapi.ListReposOutputBody, error) {
224		s.mu.Lock()
225		defer s.mu.Unlock()
226		if s.fullIndex != nil {
227			return s.fullIndex, nil
228		}
229		reposCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
230		defer cancel()
231		index, err := s.coreClient.ListRepos(reposCtx, coreapi.ListReposParams{})
232		if err != nil {
233			return nil, err
234		}
235		s.fullIndex = index
236		return index, nil
237	}
238	
239	// resolveScope resolves explicit repo filters (or the current-repo default)
240	// to index entries, deduped by repo ID. owner/name slugs use the exact-match
241	// ListRepos filter — immune to index truncation on large accounts — while raw
242	// IDs (no slash) fall back to matching against the full index. Zero matches
243	// is a clear error; a partially matched multi-repo filter proceeds with the
244	// matches, like resolveRepoFilters does for code search.
245	func (s *semanticSearchV4Session) resolveScope(ctx context.Context, slugs []string) ([]coreapi.RepoIndexEntry, error) {
246		var entries []coreapi.RepoIndexEntry
247		seen := make(map[string]bool, len(slugs))
248		for _, f := range slugs {
249			matched, err := s.lookupFilter(ctx, f)
250			if err != nil {
251				return nil, err
252			}
253			for _, e := range matched {
254				if !seen[e.ID] {
255					seen[e.ID] = true
256					entries = append(entries, e)
257				}
258			}
259		}
260		if len(entries) == 0 {
261			return nil, fmt.Errorf("no matching repositories found for %v (is the repo mirrored to Entire?)", slugs)
262		}
263		return entries, nil
264	}
265	
266	// lookupFilter resolves one repo filter to index entries, cached per session.
267	// Matching mirrors resolveRepoFilters: a gh/ prefix is stripped, owner/name
268	// matches full_name (case-insensitive, server-side exact match), and a raw
269	// ULID matches the index entry's ID.
270	func (s *semanticSearchV4Session) lookupFilter(ctx context.Context, filter string) ([]coreapi.RepoIndexEntry, error) {
271		s.mu.Lock()
272		if cached, ok := s.slugRepos[filter]; ok {
273			s.mu.Unlock()
274			return cached, nil
275		}
276		s.mu.Unlock()
277	
278		slug := strings.TrimPrefix(filter, "gh/")
279		var matched []coreapi.RepoIndexEntry
280		if strings.Contains(slug, "/") {
281			lookupCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
282			defer cancel()
283			out, err := s.coreClient.ListRepos(lookupCtx, coreapi.ListReposParams{Filter: coreapi.NewOptString(slug)})
284			if err != nil {
285				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
286			}
287			matched = out.Repos
288		} else {
289			// Raw repo ID — the exact-match filter only matches full_name, so
290			// match by ID against the full index.
291			index, err := s.listFullIndex(ctx)
292			if err != nil {
293				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
294			}
295			_, matched = resolveRepoFilters([]string{filter}, index.Repos)
296		}
297	
298		s.mu.Lock()
299		if s.slugRepos == nil {
300			s.slugRepos = make(map[string][]coreapi.RepoIndexEntry)
301		}
302		s.slugRepos[filter] = matched
303		s.mu.Unlock()
304		return matched, nil
305	}
