// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash
// and worktree identifier. The worktree ID should be empty for the main worktree
// or the internal git worktree name for linked worktrees.
// Format: entire/<commit[:7]>-<hash(worktreeID)[:6]>
func ShadowBranchNameForCommit(baseCommit, worktreeID string) string {
	commitPart := baseCommit
	if len(baseCommit) >= ShadowBranchHashLength {
		commitPart = baseCommit[:ShadowBranchHashLength]
	}
	worktreeHash := HashWorktreeID(worktreeID)
	return ShadowBranchPrefix + commitPart + "-" + worktreeHash
}

// ParseShadowBranchName extracts the commit prefix and worktree hash from a shadow branch name.
// Input format: "entire/<commit[:7]>-<worktreeHash[:6]>"
// Returns (commitPrefix, worktreeHash, ok). Returns ("", "", false) if not a valid shadow branch.
func ParseShadowBranchName(branchName string) (commitPrefix, worktreeHash string, ok bool) {
	if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
		return "", "", false
	}
	suffix := strings.TrimPrefix(branchName, ShadowBranchPrefix)

	// Find the last dash - everything before is commit prefix, after is worktree hash
	lastDash := strings.LastIndex(suffix, "-")
	if lastDash == -1 || lastDash == 0 || lastDash == len(suffix)-1 {
		// No dash, or dash at start/end - invalid format
		// Could be old format "entire/<commit[:7]>" without worktree hash
		return suffix, "", true // Return as commit prefix with empty worktree hash
	}

	return suffix[:lastDash], suffix[lastDash+1:], true
}

// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
// Returns (parentHash, baseTreeHash, error).
func (s *ephemeralStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(branchName)
	ref, err := s.repo.Reference(refName, true)

package checkpoint

import (
	"context"
	"slices"

	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// PersistentRefs is the committed-metadata ref topology.
type PersistentRefs struct {
	Primary plumbing.ReferenceName
	Read    plumbing.ReferenceName
	Push    []plumbing.ReferenceName

	// localReadOnly pins reads to the local Read ref with no remote-tracking
	// tiers at all — set via PrimaryAsLocalRead. Guards (attach's
	// local-presence gates) that must answer "would the next LOCAL write see
	// this checkpoint?" need it: the ordinary read chain selects per
	// checkpoint across local and remote-tracking trees, so a checkpoint
	// present only on a remote would otherwise read as present and a write
	// based on the stale local branch would clobber the remote on push.
	localReadOnly bool
}

// DefaultV1Refs returns the v1-only topology.
func DefaultV1Refs() PersistentRefs {
	v1Branch := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	return PersistentRefs{
		Primary: v1Branch,
		Read:    v1Branch,
		Push:    []plumbing.ReferenceName{v1Branch},
	}
}

// PrimaryFetchableFromRemote reports whether Primary has a remote-tracking
// shadow on whichever remote carries checkpoint data (the caller supplies the
// remote-tracking ref).
func (r PersistentRefs) PrimaryFetchableFromRemote() bool {
	return r.Primary.IsBranch() && slices.Contains(r.Push, r.Primary)
}

// ReadBootstrappableFromRemote reports whether reads can be bootstrapped from
// whichever remote carries checkpoint data (the caller supplies the
// remote-tracking ref): true when reads target Primary and Primary is
// fetchable from a remote, and the topology was not pinned local-only.
func (r PersistentRefs) ReadBootstrappableFromRemote() bool {
	return !r.localReadOnly && r.Read == r.Primary && r.PrimaryFetchableFromRemote()
}

// PrimaryAsRead returns a copy of r with Read pinned to Primary.
func (r PersistentRefs) PrimaryAsRead() PersistentRefs {
	r.Read = r.Primary
	return r
}

// PrimaryAsLocalRead returns a copy of r with Read pinned to Primary and
// every remote read tier disabled — see the localReadOnly field for when a
// caller needs this instead of PrimaryAsRead.
func (r PersistentRefs) PrimaryAsLocalRead() PersistentRefs {
	r.Read = r.Primary
	r.localReadOnly = true
	return r
}

// ResolveRefs returns the committed metadata topology.
func ResolveRefs(_ context.Context) PersistentRefs {
	return DefaultV1Refs()
}
// Package checkpoint provides types and interfaces for checkpoint storage.
//
// A Checkpoint captures a point-in-time within a session, containing either
// full state (Temporary) or metadata with a commit reference (Committed).
//
// See docs/architecture/sessions-and-checkpoints.md for the full domain model.
package checkpoint

import (
	"context"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"

	"github.com/go-git/go-git/v6/plumbing"
)

// Checkpoint represents a save point within a session.
type Checkpoint struct {
	// ID is the unique checkpoint identifier
	ID string

	// SessionID is the session this checkpoint belongs to
	SessionID string

	// Timestamp is when this checkpoint was created
	Timestamp time.Time

	// Type indicates temporary (full state) or committed (metadata only)
	Type Type

	// Message is a human-readable description of the checkpoint
	Message string
}

// Type indicates the storage location and lifecycle of a checkpoint.
type Type int

const (
	// Ephemeral checkpoints contain full state (code + metadata) and are stored
	// on shadow branches (entire/<commit-hash>). Holds pending intra-session state.
	Ephemeral Type = iota

	// Persistent checkpoints contain metadata + commit reference and are stored
	// on the entire/checkpoints/v1 branch. They are the permanent record.
	Persistent
)

// EphemeralStore provides the production shadow-branch checkpoint surface.
type EphemeralStore interface {
	Write(ctx context.Context, req EphemeralWriteRequest) (WriteEphemeralResult, error)
	Read(ctx context.Context, baseCommit, worktreeID string) (*ReadEphemeralResult, error)
	List(ctx context.Context) ([]EphemeralInfo, error)
	ListCheckpoints(ctx context.Context, baseCommit, worktreeID, sessionID string, limit int) ([]EphemeralCheckpointInfo, error)
	ListCheckpointsForBranch(ctx context.Context, branchName, sessionID string, limit int) ([]EphemeralCheckpointInfo, error)
	ListAllCheckpoints(ctx context.Context, sessionID string, limit int) ([]EphemeralCheckpointInfo, error)
	GetTranscriptFromCommit(ctx context.Context, commitHash plumbing.Hash, metadataDir string, agentType types.AgentType) ([]byte, error)
	ShadowBranchExists(baseCommit, worktreeID string) bool
}

// WriteEphemeralResult contains the result of writing a temporary checkpoint.
type WriteEphemeralResult struct {
	// CommitHash is the hash of the created or existing checkpoint commit
	CommitHash plumbing.Hash

	// Skipped is true if the checkpoint was skipped due to no changes
	// (tree hash matched the previous checkpoint)
	Skipped bool
}

// WriteEphemeralOptions contains options for writing a temporary checkpoint.
type WriteEphemeralOptions struct {
	// SessionID is the session identifier
	SessionID string

	// BaseCommit is the commit hash this session is based on
	BaseCommit string

	// WorktreeID is the internal git worktree identifier (empty for main worktree)
	// Used to create worktree-specific shadow branch names
	WorktreeID string

	// ModifiedFiles are files that have been modified (relative paths)
	ModifiedFiles []string

	// NewFiles are files that have been created (relative paths)
	NewFiles []string

	// DeletedFiles are files that have been deleted (relative paths)
	DeletedFiles []string

	// MetadataDir is the repo-relative path to the metadata directory
	// (.entire/metadata/<session>). It doubles as the git tree path the
	// directory's files land at, and as the name the .entire root reads them
	// through — there is deliberately no absolute counterpart, because two
	// spellings of one directory is how they come to disagree.
	MetadataDir string

	// CommitMessage is the commit subject line
	CommitMessage string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// IsFirstCheckpoint indicates if this is the first checkpoint of the session
	// When true, all working directory files are captured (not just modified)
	IsFirstCheckpoint bool
}

// ReadEphemeralResult contains the result of reading a temporary checkpoint.
type ReadEphemeralResult struct {
	// CommitHash is the hash of the checkpoint commit
	CommitHash plumbing.Hash

	// TreeHash is the hash of the tree containing the checkpoint state
	TreeHash plumbing.Hash

	// SessionID is the session identifier from the commit trailer
	SessionID string

	// MetadataDir is the metadata directory path from the commit trailer
	MetadataDir string

	// Timestamp is when the checkpoint was created
	Timestamp time.Time
}

