package cli

import (
	"context"
	"fmt"
	"io"
	"slices"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// Friendly aliases for the two selectable checkpoint backends. Users type these
// on --checkpoint-backend; they map to the canonical backend types stored in
// settings (checkpoint.BackendTypeGitBranch / checkpoint.BackendTypeGitRefs).
const (
	checkpointBackendBranchAlias = "branch"
	checkpointBackendRefsAlias   = "refs"
)

// checkpointBackendFlagUsage is the shared --checkpoint-backend help text. Both
// `enable` and `configure` register the flag, so it lives here rather than being
// spelled twice: the two commands drifting would advertise two different stories
// about which backend a repo gets.
//
// It names refs as the default rather than merely "recommended", because that is
// what a first-time `entire enable` writes, with no prompt (see
// resolveFirstRunCheckpointBackend). branch is labelled legacy: it is an explicit
// escape hatch for interoperating with older clients, not a co-equal choice.
const checkpointBackendFlagUsage = "Checkpoint storage backend: " +
	checkpointBackendRefsAlias + " (default; one git ref per checkpoint) or " +
	checkpointBackendBranchAlias + " (legacy shared entire/checkpoints/v1 branch)"

// resolveCheckpointBackendType maps a user-facing backend name to the canonical
// settings backend type and validates it may serve as the primary. It accepts
// the friendly aliases "branch"/"refs" and the canonical "git-branch"/"git-refs"
// (case-insensitive). An unknown or non-git-backed value is rejected via the
// checkpoint registry, so the error text stays in sync with the backend list.
func resolveCheckpointBackendType(name string) (string, error) {
	typ := strings.ToLower(strings.TrimSpace(name))
	switch typ {
	case checkpointBackendBranchAlias:
		typ = checkpoint.BackendTypeGitBranch
	case checkpointBackendRefsAlias:
		typ = checkpoint.BackendTypeGitRefs
	}
	if err := checkpoint.ValidatePrimaryBackend(typ); err != nil {
		return "", fmt.Errorf("invalid --%s: %w", flagCheckpointBackend, err)
	}
	return typ, nil
}

// applyCheckpointBackend sets the primary checkpoint backend on settings,
// preserving any existing mirrors except one whose type would collide with the
// new primary (the one-of-each-type topology rule enforced in checkpoint.Open).
// Switching the primary on an existing repo is safe: new checkpoints use the new
// backend while read routing keeps prior checkpoints readable in their original
// format.
func applyCheckpointBackend(s *EntireSettings, typ string) {
	cfg := s.Checkpoints
	if cfg == nil {
		cfg = &settings.CheckpointsConfig{}
	}
	cfg.Primary = settings.BackendConfig{Type: typ}
	cfg.Mirrors = slices.DeleteFunc(cfg.Mirrors, func(m settings.BackendConfig) bool {
		return m.Type == typ
	})
	s.Checkpoints = cfg
}

// applyCheckpointBackendFlag resolves and applies a --checkpoint-backend value to
// settings when it is non-empty; a no-op otherwise. Used by the fresh-repo enable
// paths (interactive setup and --agent), which mutate an in-memory settings
// object before their own save. Existing-repo enable and configure use
// updateCheckpointBackend instead.
func applyCheckpointBackendFlag(s *EntireSettings, backend string) error {
	if backend == "" {
		return nil
	}
	typ, err := resolveCheckpointBackendType(backend)
	if err != nil {
		return err
	}
	applyCheckpointBackend(s, typ)
	return nil
}

// updateCheckpointBackend persists opts.CheckpointBackend to the target settings
// file. Used by `entire configure` and by `entire enable` on repos that are
// already set up (both operate on an on-disk file rather than the in-memory
// settings the fresh-setup flow builds).
func updateCheckpointBackend(ctx context.Context, w io.Writer, opts EnableOptions) error {
	typ, err := resolveCheckpointBackendType(opts.CheckpointBackend)
	if err != nil {
		return err
	}

	targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
	targetFileAbs, err := paths.AbsPath(ctx, targetFile)
	if err != nil {
		targetFileAbs = targetFile
	}

	s, err := settings.LoadFromFile(targetFileAbs)
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	applyCheckpointBackend(s, typ)

	if err := saveSettingsToTarget(ctx, s, targetFile); err != nil {
		return fmt.Errorf("failed to save settings: %w", err)
	}

	fmt.Fprintf(w, "✓ Checkpoint backend set to %s (%s)\n", typ, configDisplay)
	return nil
}
}

// resolveFirstRunCheckpointBackend decides the checkpoint storage backend
// the setup flow writes. An explicit --checkpoint-backend always wins;
// otherwise a first run takes the git-refs default silently (branch remains
// selectable via --checkpoint-backend branch). The choice is written
// explicitly into the new settings file, and the config-less runtime
// fallback stays git-branch so existing repos are untouched. The default is
// empty — write nothing — while ENTIRE_CHECKPOINTS_PRIMARY is active
// (firstRunCheckpointBackendDefault returns ""): the env fully replaces
// settings, so persisting a default would only write diverging config.
func resolveFirstRunCheckpointBackend(opts EnableOptions, firstRun bool) string {
	if opts.CheckpointBackend != "" {
		return opts.CheckpointBackend
	}
	if firstRun {
		return firstRunCheckpointBackendDefault()
	}
	return ""
}

// firstRunCheckpointBackendDefault is the backend written on first-time
// setups when --checkpoint-backend wasn't passed: the git-refs store (a
// storage-topology question is unanswerable during first-time setup). Empty —
// write nothing — while the ENTIRE_CHECKPOINTS_PRIMARY override is active:
// the env fully replaces any settings block, so persisting a default here
// would write config that diverges from the backend actually in use (and
// break harnesses that pin git-branch via the env).
func firstRunCheckpointBackendDefault() string {
	if os.Getenv(settings.EnvCheckpointsPrimary) != "" {
		return ""
	}
	return checkpointBackendRefsAlias
}

// runEnable flips the enabled flag to true in the scope chosen by the caller
// (see setEnabledFlag). Callers resolve the scope: runEnableOnConfiguredRepo
// uses settingsTargetFile so a bare `entire enable` targets the committed
// settings.json when present and can recover a repo disabled there.
func runEnable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
	if err := setEnabledFlag(ctx, true, useProjectSettings); err != nil {
		return err
	}

	fmt.Fprintln(w, "Entire is now enabled.")
	printEnabledStatus(ctx, w)
}

// buildKindReadStores returns the git-branch and git-refs read stores used for
// id-kind read routing, reusing the already-built primary for whichever kind it
// is and constructing the sibling. A non-branch/refs git-backed primary (not a
// real configuration today, since buildPrimary only accepts git-backed backends)
// yields both freshly built git stores.
func buildKindReadStores(ctx context.Context, env OpenEnv, primaryType string, primary PersistentStore) (branch, refs PersistentStore, err error) {
	switch primaryType {
	case BackendTypeGitBranch:
		branch = primary
		refs, err = build(ctx, env, BackendTypeGitRefs, nil)
	case BackendTypeGitRefs:
		refs = primary
		branch, err = build(ctx, env, BackendTypeGitBranch, nil)
	default:
		if branch, err = build(ctx, env, BackendTypeGitBranch, nil); err == nil {
			refs, err = build(ctx, env, BackendTypeGitRefs, nil)
		}
	}
	return branch, refs, err
}

// resolvePrimaryType returns the configured primary backend type, defaulting to
// the git-branch backend when none is configured.
func resolvePrimaryType(cfg *settings.CheckpointsConfig) string {
	if cfg != nil && cfg.Primary.Type != "" {
		return cfg.Primary.Type
	}
	return BackendTypeGitBranch
}

// primaryConfig returns the primary backend's config block, if any.
func primaryConfig(cfg *settings.CheckpointsConfig) json.RawMessage {
	if cfg == nil {
		return nil
	}
	return cfg.Primary.Config
}

// buildPrimary constructs the primary persistent store. The primary must be a
// git-backed backend: attach, resume, push, doctor, cleanup, and OPF all drive
// the primary's record through the repo and its refs, so a non-git-backed
// primary is rejected rather than silently half-supported.
func buildPrimary(ctx context.Context, env OpenEnv, typ string, raw json.RawMessage) (PersistentStore, error) {
	if err := ValidatePrimaryBackend(typ); err != nil {
		return nil, fmt.Errorf("checkpoints.primary: %w", err)
	}
	return build(ctx, env, typ, raw)
}

// buildMirrors constructs the mirror writers. Each backend type may appear at
// most once across the topology (primary + mirrors), so a mirror cannot reuse
// the primary's type or another mirror's. This is the conservative form of "no
// two backends may write the same target": today two backends of the same type
// share the same refs/storage, so a duplicate type is a guaranteed collision
// (e.g. a git-branch mirror under a git-branch primary would double-write the v1
// branch). A future per-mirror config (same backend type pointed at a distinct
// repo/refs) could relax this; for now it is one of each type.
func buildMirrors(ctx context.Context, env OpenEnv, cfg *settings.CheckpointsConfig, primaryType string) ([]Writer, error) {
	if cfg == nil || len(cfg.Mirrors) == 0 {
		return nil, nil
	}
	seen := map[string]bool{primaryType: true}
	mirrors := make([]Writer, 0, len(cfg.Mirrors))
	for i, m := range cfg.Mirrors {
		if _, err := lookupBackend(m.Type); err != nil {
			return nil, fmt.Errorf("checkpoints.mirrors[%d]: %w", i, err)
		}
		if seen[m.Type] {
			return nil, fmt.Errorf("checkpoints.mirrors[%d]: backend type %q is already used by the primary or another mirror; each backend type may appear at most once", i, m.Type)
		}
		seen[m.Type] = true
		// Mirrors are best-effort write-only copies whose failures are logged
		// and dropped; never pay on-demand ref-fetch network probes for them.
		mirrorEnv := env
		mirrorEnv.RefFetcher = nil
		store, err := build(ctx, mirrorEnv, m.Type, m.Config)
		if err != nil {
			return nil, fmt.Errorf("checkpoints.mirrors[%d]: %w", i, err)
		}
		mirrors = append(mirrors, store)
	}
	return mirrors, nil
}

func resolveOpenRefs(ctx context.Context, opts OpenOptions) PersistentRefs {
	if opts.Refs != nil {
		return *opts.Refs
	}
	return ResolveRefs(ctx)
}

// Ephemeral returns the git-backed shadow-branch (temporary) store.
func (s *Stores) Ephemeral() EphemeralStore { return s.ephemeral }

// Refs returns the resolved committed-ref topology.
func (s *Stores) Refs() PersistentRefs { return s.refs }

